diff --git a/src/main/java/hotel/messages/ArchiveCopyHandler.java b/src/main/java/hotel/messages/ArchiveCopyHandler.java
new file mode 100644
index 0000000..061861b
--- /dev/null
+++ b/src/main/java/hotel/messages/ArchiveCopyHandler.java
@@ -0,0 +1,24 @@
+package hotel.messages;
+
+/**
+ * Sends a copy of every message to the archive address, so the accountant has a record of everything
+ * the inn sent. The copy has the same text and the subject starts with "[Cópia] ". Blocked messages
+ * do not generate a copy.
+ */
+final class ArchiveCopyHandler implements EmailHandler {
+
+    private static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
+    private final boolean enabled;
+
+    ArchiveCopyHandler(boolean enabled) {
+        this.enabled = enabled;
+    }
+
+    @Override
+    public boolean handle(EmailContext context) {
+        if (enabled && context.status == MessageStatus.SENT) {
+            context.addMessage(ARCHIVE_ADDRESS, "[Cópia] " + context.subject, context.body, MessageStatus.SENT);
+        }
+        return true;
+    }
+}
diff --git a/src/main/java/hotel/messages/EmailContext.java b/src/main/java/hotel/messages/EmailContext.java
new file mode 100644
index 0000000..2c7c818
--- /dev/null
+++ b/src/main/java/hotel/messages/EmailContext.java
@@ -0,0 +1,33 @@
+package hotel.messages;
+
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * The data of an e-mail as it goes through the chain of handlers. Handlers can modify the message,
+ * block it, or add copies that will also be stored.
+ */
+final class EmailContext {
+
+    String to;
+    String subject;
+    String body;
+    MessageStatus status = MessageStatus.SENT;
+    private final List<MessageRecord> additionalMessages = new ArrayList<>();
+
+    EmailContext(String to, String subject, String body) {
+        this.to = to;
+        this.subject = subject;
+        this.body = body;
+    }
+
+    void addMessage(String to, String subject, String body, MessageStatus status) {
+        additionalMessages.add(new MessageRecord(to, subject, body, status));
+    }
+
+    List<MessageRecord> additionalMessages() {
+        return List.copyOf(additionalMessages);
+    }
+
+    record MessageRecord(String to, String subject, String body, MessageStatus status) {}
+}
diff --git a/src/main/java/hotel/messages/EmailHandler.java b/src/main/java/hotel/messages/EmailHandler.java
new file mode 100644
index 0000000..0779478
--- /dev/null
+++ b/src/main/java/hotel/messages/EmailHandler.java
@@ -0,0 +1,14 @@
+package hotel.messages;
+
+/**
+ * One step in the chain that processes an e-mail before it is sent. A handler can modify the message,
+ * block it (mark it as BLOCKED), or add extra messages (such as copies).
+ */
+interface EmailHandler {
+
+    /**
+     * Processes the e-mail. Returns true if the next handler should run, or false to stop the chain
+     * (for instance, when the message is blocked).
+     */
+    boolean handle(EmailContext context);
+}
diff --git a/src/main/java/hotel/messages/EmailSender.java b/src/main/java/hotel/messages/EmailSender.java
index 3eee255..830272c 100644
--- a/src/main/java/hotel/messages/EmailSender.java
+++ b/src/main/java/hotel/messages/EmailSender.java
@@ -1,15 +1,44 @@
 package hotel.messages;

+import java.util.ArrayList;
+import java.util.List;
+
 /** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
 public final class EmailSender {

     private final SentMessages sentMessages;
+    private final List<EmailHandler> handlers;

-    public EmailSender(SentMessages sentMessages) {
+    public EmailSender(SentMessages sentMessages, boolean testMode, boolean archiveCopyEnabled) {
         this.sentMessages = sentMessages;
+        this.handlers = buildHandlerChain(testMode, archiveCopyEnabled);
     }

     public Message send(String to, String subject, String body) {
-        return sentMessages.add("EMAIL", to, subject, body);
+        EmailContext context = new EmailContext(to, subject, body);
+
+        for (EmailHandler handler : handlers) {
+            if (!handler.handle(context)) {
+                break;
+            }
+        }
+
+        Message primaryMessage = sentMessages.add("EMAIL", context.to, context.subject, context.body, context.status);
+
+        for (EmailContext.MessageRecord additional : context.additionalMessages()) {
+            sentMessages.add("EMAIL", additional.to(), additional.subject(), additional.body(), additional.status());
+        }
+
+        return primaryMessage;
+    }
+
+    private static List<EmailHandler> buildHandlerChain(boolean testMode, boolean archiveCopyEnabled) {
+        List<EmailHandler> chain = new ArrayList<>();
+        chain.add(new EmailValidator());
+        chain.add(new TestModeHandler(testMode));
+        if (!testMode) {
+            chain.add(new ArchiveCopyHandler(archiveCopyEnabled));
+        }
+        return chain;
     }
 }
diff --git a/src/main/java/hotel/messages/EmailValidator.java b/src/main/java/hotel/messages/EmailValidator.java
new file mode 100644
index 0000000..e6c0713
--- /dev/null
+++ b/src/main/java/hotel/messages/EmailValidator.java
@@ -0,0 +1,30 @@
+package hotel.messages;
+
+/**
+ * Validates the e-mail address. An invalid address causes the message to be blocked: it will not be
+ * sent and will appear in the list as BLOCKED, so the front desk can call the guest.
+ *
+ * <p>A valid address has exactly one @, something before it, and after it a name with at least one dot
+ * (like ana@gmail.com).
+ */
+final class EmailValidator implements EmailHandler {
+
+    @Override
+    public boolean handle(EmailContext context) {
+        if (!isValid(context.to)) {
+            context.status = MessageStatus.BLOCKED;
+            return false;
+        }
+        return true;
+    }
+
+    private static boolean isValid(String email) {
+        int atIndex = email.indexOf('@');
+        if (atIndex <= 0 || atIndex != email.lastIndexOf('@')) {
+            return false;
+        }
+        String localPart = email.substring(0, atIndex);
+        String domainPart = email.substring(atIndex + 1);
+        return !localPart.isEmpty() && domainPart.contains(".");
+    }
+}
