+        if (!testMode) {
+            return true;
+        }
+        String originalRecipient = context.to;
+        context.to = TEST_ADDRESS;
+        context.subject = "[TESTE] " + context.subject;
+        context.body = "Destinatário original: " + originalRecipient + "\n" + context.body;
+        return true;
+    }
+}
