+        assertEquals("Destinatário original: ana@gmail.com\nOlá Ana", all.get(0).body());
+        assertEquals(MessageStatus.SENT, all.get(0).status());
+    }
+
+    @Test
+    void testModeDoesNotCreateArchiveCopy() {
